const projects=[
{no:"01",slug:"ufls-smartgrid",field:{en:"Power systems · protection logic",fr:"Réseaux électriques · protection"},title:"Smart-Grid UFLS Relay — ONEE & SENELEC",body:{en:"UFLS relay model for two grid contexts, with a six-state Stateflow automaton for staged shedding, restoration and validation.",fr:"Modèle de relais UFLS pour deux contextes de réseau, avec un automate Stateflow à six états pour le délestage, la restauration et la validation."},problem:{en:"Frequency events require protection logic that reacts quickly without hiding the assumptions behind each threshold.",fr:"Les événements de fréquence exigent une logique de protection rapide, sans masquer les hypothèses derrière chaque seuil."},solution:{en:"A staged UFLS controller with explicit states, thresholds and restoration rules.",fr:"Un contrôleur UFLS par paliers, avec états, seuils et règles de restauration explicitement définis."},steps:{en:["Define grid assumptions and frequency thresholds.","Build the Stateflow state machine.","Run disturbance scenarios.","Check staged shedding and restoration behaviour."],fr:["Définir les hypothèses réseau et les seuils de fréquence.","Construire l’automate Stateflow.","Tester les scénarios de perturbation.","Vérifier le délestage par paliers et la restauration."]},discussion:{en:"The value of the model is traceability: when the relay acts, why it acts, and how the grid returns toward normal operation remain visible.",fr:"La valeur du modèle est la traçabilité : quand le relais agit, pourquoi il agit et comment le réseau revient vers un fonctionnement normal."},links:[["GitHub","https://github.com/diawbirane10-lgtm/ufls-smartgrid-onee-senelec"],["Report EN","https://raw.githubusercontent.com/diawbirane10-lgtm/bdiaw/main/public/documents/ufls_smartgrid_project_report_EN.pdf"],["Rapport FR","https://raw.githubusercontent.com/diawbirane10-lgtm/bdiaw/main/public/documents/rapport_projet_ufls_smartgrid_FR.pdf"]]},
{no:"02",slug:"wave-energy-conversion",field:{en:"Renewable energy · machine control",fr:"Énergie renouvelable · commande"},title:"Wave-Energy Conversion Chain — FOC & Grid Injection",body:{en:"Simulation of a wave-energy conversion chain using a PMSG, field-oriented control and grid-side injection.",fr:"Simulation d’une chaîne houlomotrice avec GSAP, commande vectorielle et injection côté réseau."},problem:{en:"Wave input is variable; the electrical chain must regulate power without pretending the source is stable.",fr:"L’entrée houlomotrice est variable ; la chaîne électrique doit réguler la puissance sans faire comme si la source était stable."},solution:{en:"A PMSG conversion model with field-oriented control and grid-injection logic.",fr:"Un modèle de conversion par GSAP avec commande vectorielle et logique d’injection réseau."},steps:{en:["Model the mechanical-to-electrical conversion chain.","Set the machine-control assumptions.","Connect the control loop to the grid-side stage.","Discuss the limits of the simulation."],fr:["Modéliser la chaîne de conversion mécanique-électrique.","Définir les hypothèses de commande machine.","Relier la boucle de commande à l’étage côté réseau.","Discuter les limites de la simulation."]},discussion:{en:"The project connects renewable-energy modelling with machine-control practice and shows where variability enters the system.",fr:"Le projet relie la modélisation d’énergie renouvelable à la commande de machine et montre où la variabilité entre dans le système."},links:[["Project report","https://raw.githubusercontent.com/diawbirane10-lgtm/bdiaw/main/public/documents/projet-houlomotrice.pdf"]]},
{no:"03",slug:"railway-traction-25kv",field:{en:"Railway electrification · energy recovery",fr:"Électrification ferroviaire · énergie"},title:"25 kV AC Railway Traction System",body:{en:"Traction-chain model linking 25 kV AC supply assumptions, train dynamics, catenary behaviour, converter control and regenerative braking.",fr:"Modèle de chaîne de traction reliant alimentation 25 kV AC, dynamique du train, caténaire, convertisseur et freinage régénératif."},problem:{en:"Traction systems mix infrastructure, converters and moving loads; treating them separately hides system behaviour.",fr:"Les systèmes de traction combinent infrastructure, convertisseurs et charges mobiles ; les isoler masque le comportement global."},solution:{en:"A full-chain model connecting supply assumptions, train dynamics and energy recovery.",fr:"Un modèle de chaîne complète reliant hypothèses d’alimentation, dynamique du train et récupération d’énergie."},steps:{en:["Define the 25 kV AC supply context.","Model the traction demand.","Represent converter and catenary constraints.","Analyse regenerative-braking contribution."],fr:["Définir le contexte d’alimentation 25 kV AC.","Modéliser la demande de traction.","Représenter les contraintes convertisseur et caténaire.","Analyser l’apport du freinage régénératif."]},discussion:{en:"The case shows where energy moves, where constraints appear and what regenerative braking adds to the system.",fr:"Le cas montre où circule l’énergie, où apparaissent les contraintes et ce que le freinage régénératif apporte au système."},links:[["Report EN","https://raw.githubusercontent.com/diawbirane10-lgtm/bdiaw/main/public/documents/railway_traction_project_report_EN.pdf"],["Rapport FR","https://raw.githubusercontent.com/diawbirane10-lgtm/bdiaw/main/public/documents/rapport_projet_traction_FR.pdf"]]},
{no:"04",slug:"digital-twin-liion-battery",field:{en:"Battery systems · engineering software",fr:"Batteries · logiciel"},title:"Digital Twin — Li-ion Battery Packs",body:{en:"Battery-pack digital twin around a Thevenin 2RC model, SOC, SOH/RUL, thermal behaviour and a lightweight app layer.",fr:"Jumeau numérique batterie avec modèle Thevenin 2RC, SOC, SOH/RUL, thermique et couche applicative légère."},problem:{en:"A battery pack cannot be understood only through voltage; internal state, degradation and temperature need to be visible.",fr:"Un pack batterie ne se comprend pas seulement par la tension ; l’état interne, la dégradation et la température doivent être visibles."},solution:{en:"A digital twin combining equivalent-circuit modelling, state estimation, degradation indicators and thermal behaviour.",fr:"Un jumeau numérique combinant modèle circuit équivalent, estimation d’état, indicateurs de dégradation et comportement thermique."},steps:{en:["Implement the Thevenin 2RC representation.","Estimate SOC and track health indicators.","Add thermal behaviour.","Expose scenarios through a lightweight interface."],fr:["Implémenter la représentation Thevenin 2RC.","Estimer le SOC et suivre les indicateurs de santé.","Ajouter le comportement thermique.","Exposer les scénarios dans une interface légère."]},discussion:{en:"The value is inspection: comparing scenarios and making battery behaviour easier to explain.",fr:"La valeur est l’inspection : comparer des scénarios et rendre le comportement batterie plus explicable."},links:[["GitHub","https://github.com/diawbirane10-lgtm/Digital_Twin_Li-ion_Batt_Packs"],["Live app","https://digitwinbattpacks1.streamlit.app/"],["Report","https://raw.githubusercontent.com/diawbirane10-lgtm/bdiaw/main/public/documents/Rapport_Digital_Twin_LiIon.pdf"]]},
{no:"05",slug:"digital-twin-electric-drive",field:{en:"Electric drives · control",fr:"Entraînements électriques · commande"},title:"Digital Twin — Variable-Speed Electric Drive",body:{en:"Electric-drive digital twin using state-space modelling, numerical integration, H-bridge representation, cascade PI control and signal analysis.",fr:"Jumeau numérique d’un entraînement électrique avec modèle d’état, intégration numérique, pont en H, PI en cascade et analyse de signal."},problem:{en:"A drive model is useful only when the machine, converter and controller can be inspected together.",fr:"Un modèle d’entraînement n’est utile que si la machine, le convertisseur et le contrôleur peuvent être inspectés ensemble."},solution:{en:"A compact simulation chain connecting the model, converter representation and cascade PI control.",fr:"Une chaîne de simulation compacte reliant le modèle, la représentation du convertisseur et la commande PI en cascade."},steps:{en:["Build the state-space model.","Represent the H-bridge stage.","Tune the cascade PI control.","Analyse the simulated response."],fr:["Construire le modèle d’état.","Représenter l’étage pont en H.","Régler la commande PI en cascade.","Analyser la réponse simulée."]},discussion:{en:"The project keeps the control action understandable from assumptions to simulated response.",fr:"Le projet garde l’action de commande compréhensible depuis les hypothèses jusqu’à la réponse simulée."},links:[["GitHub","https://github.com/diawbirane10-lgtm/digital-twin-motor"],["Report","https://raw.githubusercontent.com/diawbirane10-lgtm/bdiaw/main/public/documents/Digital_Twin_complet-report.pdf"]]}];

