const copy={en:{lang:"FR",title:"Birane DIAW",subtitle:"State Engineering Student — Electrical Engineering & Intelligent Systems.",intro:"My work focuses on electrical engineering, power systems, industrial automation and intelligent control. I develop engineering projects that combine modelling, simulation, control, embedded systems and practical implementation, with a strong interest in energy systems and applied research.",nav:["About","Research","Selected projects","Experience","Academic path","Skills","Contact"],research:{eyebrow:"Research",heading:"Accepted manuscript",summary:"This paper studies how grid-forming virtual synchronous machine control, supported by DC-coupled battery storage, can improve frequency stability in a renewable multi-terminal VSC-HVDC system. It connects converter behaviour, storage response and disturbance scenarios while keeping the control assumptions explicit.",meta:"Journal of Undergraduate Research International, KFUPM · JURI-00314-2026-02 · DOI forthcoming",link:"Journal website"},projects:{eyebrow:"Selected projects",heading:"Five selected engineering projects",open:"Open case study",more:"More projects",moreBody:"Additional prototypes and code repositories are available on GitHub.",github:"Open GitHub"},experience:{heading:"Engineering internships & field work",items:[["Final-Year Project Intern — Industrial Automation","Menara Préfa · Marrakech, Morocco","Apr — Jun 2026","Designed an intelligent AS/RS concept for automated mold changes on the QUADRA 10 press, with GRAFCET sequencing, RFID identification, PLC/HMI integration and simulation.","TIA Portal · GRAFCET · RFID · PLCSIM · Factory I/O","menara"],["Intern — Engineering Office & Works Supervision","S4E SARL · Dakar, Senegal","Jul — Aug 2024","Contributed to an EDG tender file, LV sizing with Camelia, AutoCAD drawing updates, and field commissioning of a 225 kV / 20 MVA transformer at Manantali.","AutoCAD · Camelia · 225 kV · Commissioning","s4e"],["High-Voltage Engineering Intern","S4E SARL · Dakar, Senegal","Jul — Aug 2023","Observed and documented HV-substation operations, updated single-line diagrams and applied HSE procedures during field visits in Senegal, Mali and Mauritania.","HV substations · Single-line diagrams · HSE","s4e"]]},path:{eyebrow:"Academic path",heading:"Engineering education",site:"School website",items:[["State Engineering Student — Electrical Engineering & Intelligent Systems","EMSI Rabat","Oct 2026 — Jun 2028","Engineering cycle focused on electrical engineering, intelligent systems and industrial technologies. The path connects power systems, smart grids, automation, supervision, embedded systems and applied engineering projects.",logos.emsi,schoolLinks.emsi],["Bachelor in Science and Techniques — Industrial Computing, Electronics, Electrical Engineering and Automation (IEEA)","FST Marrakech · Université Cadi Ayyad","Oct 2022 — Jun 2026","Four-year path combining a common scientific core in mathematics, computer science, physics and chemistry, followed by applied mathematics and a final-year reorientation toward electrical engineering. The degree now bridges modelling, industrial computing, electronics, electrotechnics and automatic control.",logos.fst,schoolLinks.fst],["Baccalauréat S2, Experimental Sciences","Cours Sainte Marie de Hann, Dakar","Jul 2022","Senegalese scientific track centred on experimental sciences, physics and mathematics. It built the base for scientific reasoning, observation, quantitative analysis and the transition toward engineering studies.",logos.csmh,schoolLinks.csmh]]},skills:{eyebrow:"Skills",heading:"Tools and methods",groups:[["Energy & power systems","Smart grids · UFLS · VSC-HVDC · Grid-forming control · PV conversion · Railway traction · Wave energy · Battery systems"],["Control & simulation","MATLAB/Simulink · Simscape Electrical · Stateflow · dq control · FOC · PID · MPC · Numerical simulation"],["Industrial automation","Siemens TIA Portal · Siemens PLCs · CODESYS 3.5 · IEC 61131-3 ST · GRAFCET · OpenPLC · SCADA concepts"],["Embedded & electronics","KiCad · PCB design · ESP32 · C/C++ basics · Sensors · Telemetry · RF concepts"],["Engineering software","Python · FastAPI · Streamlit · CustomTkinter · Git/GitHub · Data processing · Technical documentation"]]},contact:{heading:"Systems should remain understandable when they become complex.",body:"For internships, engineering collaboration or research discussions, email is the simplest entry point."},detail:["Back to portfolio","Problem","Solution","Build path","Discussion","Reports and links"]},fr:{lang:"EN",title:"Birane DIAW",subtitle:"Élève ingénieur d\'État — Génie électrique & systèmes intelligents.",intro:"Mon travail se concentre sur le génie électrique, les réseaux électriques, l’automatisation industrielle et la commande intelligente. Je développe des projets d’ingénierie qui combinent modélisation, simulation, commande, systèmes embarqués et mise en œuvre pratique, avec un intérêt particulier pour les systèmes énergétiques et la recherche appliquée.",nav:["À propos","Recherche","Projets sélectionnés","Expérience","Parcours académique","Compétences","Contact"],research:{eyebrow:"Recherche",heading:"Manuscrit accepté",summary:"Cet article étudie comment une commande grid-forming de type machine synchrone virtuelle, appuyée par un stockage batterie couplé côté DC, peut améliorer la stabilité fréquentielle d’un système VSC-HVDC multi-terminal à forte part renouvelable. Il relie le comportement des convertisseurs, la réponse du stockage et les scénarios de perturbation, avec des hypothèses de commande explicites.",meta:"Journal of Undergraduate Research International, KFUPM · JURI-00314-2026-02 · DOI à venir",link:"Site du journal"},projects:{eyebrow:"Projets sélectionnés",heading:"Cinq projets d’ingénierie sélectionnés",open:"Ouvrir la fiche projet",more:"Autres projets",moreBody:"D’autres prototypes et dépôts de code sont disponibles sur GitHub.",github:"Ouvrir GitHub"},experience:{heading:"Stages & expérience terrain",items:[["Stagiaire PFE — Maintenance & automatismes industriels","Menara Préfa · Marrakech, Maroc","Avr. — Juin 2026","Conception d’un concept AS/RS intelligent pour automatiser le changement de moules sur la presse QUADRA 10, avec séquencement GRAFCET, identification RFID, intégration automate/IHM et simulation.","TIA Portal · GRAFCET · RFID · PLCSIM · Factory I/O","menara"],["Stagiaire — Bureau d’études et suivi de travaux","S4E SARL · Dakar, Sénégal","Juil. — Août 2024","Participation à un dossier d’appel d’offres EDG, dimensionnement BT avec Camelia, mise à jour de plans AutoCAD et mise en service terrain d’un transformateur 225 kV / 20 MVA à Manantali.","AutoCAD · Camelia · 225 kV · Mise en service","s4e"],["Stagiaire — Haute tension","S4E SARL · Dakar, Sénégal","Juil. — Août 2023","Observation et documentation d’installations HT, mise à jour de schémas unifilaires et application des procédures HSE lors de visites terrain au Sénégal, au Mali et en Mauritanie.","Postes HT · Schémas unifilaires · HSE","s4e"]]},path:{eyebrow:"Parcours académique",heading:"Formation d’ingénieur",site:"Site de l’école",items:[["Élève ingénieur d\'État — Génie électrique & systèmes intelligents","EMSI Rabat","Oct. 2026 — Juin 2028","Cycle ingénieur orienté vers le génie électrique, les systèmes intelligents et les technologies industrielles. Le parcours relie réseaux électriques, smart grids, automatisation, supervision, systèmes embarqués et projets d’ingénierie appliquée.",logos.emsi,schoolLinks.emsi],["Bachelor en sciences et techniques — IEEA : informatique industrielle, électronique, électrotechnique et automatique","FST Marrakech · Université Cadi Ayyad","Oct. 2022 — Juin 2026","Parcours de quatre ans avec un cycle commun en mathématiques, informatique, physique et chimie, puis une spécialisation en mathématiques appliquées et une réorientation en dernière année vers le génie électrique. La formation relie aujourd’hui modélisation, informatique industrielle, électronique, électrotechnique et automatique.",logos.fst,schoolLinks.fst],["Baccalauréat S2, Sciences expérimentales","Cours Sainte Marie de Hann, Dakar","Juil. 2022","Série scientifique sénégalaise centrée sur les sciences expérimentales, les sciences physiques et les mathématiques. Elle a posé les bases du raisonnement scientifique, de l’observation, de l’analyse quantitative et du passage vers les études d’ingénierie.",logos.csmh,schoolLinks.csmh]]},skills:{eyebrow:"Compétences",heading:"Outils et méthodes",groups:[["Énergie & réseaux électriques","Smart grids · UFLS · VSC-HVDC · Commande grid-forming · Conversion photovoltaïque · Traction ferroviaire · Énergie houlomotrice · Systèmes de batteries"],["Commande & simulation","MATLAB/Simulink · Simscape Electrical · Stateflow · Commande dq · FOC · PID · MPC · Simulation numérique"],["Automatisation industrielle","Siemens TIA Portal · Automates Siemens · CODESYS 3.5 · IEC 61131-3 ST · GRAFCET · OpenPLC · Concepts SCADA"],["Systèmes embarqués & électronique","KiCad · Conception de PCB · ESP32 · Bases C/C++ · Capteurs · Télémétrie · Concepts RF"],["Logiciels d’ingénierie","Python · FastAPI · Streamlit · CustomTkinter · Git/GitHub · Traitement de données · Documentation technique"]]},contact:{heading:"Les systèmes doivent rester compréhensibles même quand ils deviennent complexes.",body:"Pour un stage, une collaboration technique ou une discussion de recherche, l’email reste le point d’entrée le plus simple."},detail:["Retour au portfolio","Problème","Solution","Étapes","Discussion","Rapports et liens"]}};

function resourceLabel(label,lang){
  if(lang!=="fr")return label;
  const labels={
    "Project report":"Rapport du projet",
    "Report":"Rapport",
    "Report EN":"Rapport EN",
    "Rapport FR":"Rapport FR",
    "Live app":"Application en ligne",
    "GitHub":"GitHub"
  };
  return labels[label]||label;
}
function ExtLink({href,children,className=""}){const external=!href.startsWith("/")&&!href.startsWith("mailto:");return <a className={className} href={href} target={external?"_blank":undefined} rel={external?"noreferrer":undefined}>{children}{external?<span aria-hidden="true"> ↗</span>:null}</a>}
function Top({t,lang,setLang,theme,setTheme}){return <div className="topbar"><a className="brand" href="/"><span className="brandMark" aria-hidden="true">Ω</span><span className="brandText">OHMEGA</span></a><div className="switches"><button type="button" onClick={()=>setLang(lang==="en"?"fr":"en")}>{t.lang}</button><button className="themeButton" type="button" aria-label={lang==="fr"?(theme==="dark"?"Passer au mode clair":"Passer au mode sombre"):(theme==="dark"?"Switch to light mode":"Switch to dark mode")} title={lang==="fr"?(theme==="dark"?"Passer au mode clair":"Passer au mode sombre"):(theme==="dark"?"Switch to light mode":"Switch to dark mode")} onClick={()=>setTheme(theme==="dark"?"light":"dark")}>{theme==="dark"?"☀︎":"☾"}</button></div></div>}
function Section({id,title,subtitle,children,cut=false}){return <section id={id} className={`section${cut?" cut":""}`}><div className="sectionHead"><h2 className="sectionTitle">{title}</h2><p className="sectionSubtitle">{subtitle}</p></div><div>{children}</div></section>}
function Home({t,lang}){const[navOpen,setNavOpen]=useState(false);const navTargets=["#top","#research","#projects","#experience","#path","#skills","#contact"];return <><header className="hero" id="top"><h1>{t.title}</h1><p className="lead">{t.subtitle}</p><p className="introCopy">{t.intro}</p><button className="mobileMenuButton" type="button" aria-expanded={navOpen} aria-controls="portfolio-navigation" onClick={()=>setNavOpen(v=>!v)}><span className="hamburgerIcon" aria-hidden="true"><span></span><span></span><span></span></span><span>{lang==="fr"?"Menu":"Menu"}</span></button><nav id="portfolio-navigation" className={`nav${navOpen?" isOpen":""}`} aria-label={lang==="fr"?"Navigation du portfolio":"Portfolio navigation"}>{t.nav.map((n,i)=><a href={navTargets[i]} key={n} onClick={()=>setNavOpen(false)}>{n}</a>)}</nav></header><Section id="research" title={lang==="fr"?"Recherche & Publications":"Research & Publications"} subtitle={t.research.heading} cut><article className="paper"><div className="paperTop"><a href={juri} target="_blank" rel="noreferrer"><img src={logos.juri} alt="Journal of Undergraduate Research International logo"/></a><div><p className="meta">{lang==="fr"?"Accepté pour publication · DOI à venir":"Accepted for publication · DOI forthcoming"}</p><h3>Grid-Forming Virtual Synchronous Machine Control with DC-Coupled Battery Storage for Frequency Stability in a Multi-Terminal VSC-HVDC Renewable Power System</h3></div></div><p className="summary">{t.research.summary}</p><p className="journal">{t.research.meta}</p><nav className="inline"><ExtLink href={juri}>{t.research.link}</ExtLink></nav></article></Section><Section id="projects" title={lang==="fr"?"Projets sélectionnés":"Selected Projects"} subtitle={lang==="fr"?"Cinq études de cas d’ingénierie":"Five engineering case studies"}><div className="list">{projects.map(p=><article className="work" key={p.slug}><span>{p.no}</span><div><p>{p.field[lang]}</p><h3><ExtLink href={`/projects/${p.slug}`} className="titleLink">{p.title}</ExtLink></h3><p>{p.body[lang]}</p><div className="projectTags" aria-label={lang==="fr"?"Compétences et logiciels":"Skills and software"}>{projectTags[p.slug]?.skills[lang].map(tag=><span className="projectTag" key={`skill-${tag}`}>{tag}</span>)}{projectTags[p.slug]?.tools.map(tag=><span className="projectTag toolTag" key={`tool-${tag}`}>{tag}</span>)}</div><nav className="inline"><ExtLink href={`/projects/${p.slug}`}>{t.projects.open}</ExtLink>{p.links.slice(0,1).map(([label,href])=><ExtLink key={label} href={href}>{resourceLabel(label,lang)}</ExtLink>)}</nav></div></article>)}</div><div className="note"><p><b>{t.projects.more}</b> — {t.projects.moreBody}</p><ExtLink href={github}>{t.projects.github}</ExtLink></div></Section><Section id="experience" title={lang==="fr"?"Expérience":"Experience"} subtitle={t.experience.heading} cut><div className="experienceList">{t.experience.items.map(([role,company,date,description,tags,logoKey])=><article className="experienceItem" key={`${company}-${date}`}><span className="experienceDate">{date}</span><div className="experienceContent"><div className="experienceHeader"><div><h3>{role}</h3><p className="experienceMeta">{company}</p></div><div className={`experienceLogo ${logoKey==="menara"?"menaraLogo":"s4eLogo"}`}><img src={experienceLogos[logoKey]} alt={`${company.split(" · ")[0]} logo`}/></div></div><p className="experienceBody">{description}</p><div className="experienceTags">{tags.split(" · ").map(tag=><span className="experienceTag" key={tag}>{tag}</span>)}</div></div></article>)}</div></Section><Section id="path" title={lang==="fr"?"Parcours académique":"Academic Path"} subtitle={t.path.heading} cut><div className="list">{t.path.items.map(([title,place,date,description,logo,href])=><article className="time" key={title}><a className="schoolLogo" href={href} target="_blank" rel="noreferrer"><img src={logo} alt={`${place} logo`}/></a><div><h3>{title}</h3><p>{place}</p><p className="timeBody">{description}</p><nav className="inline schoolLink"><ExtLink href={href}>{t.path.site}</ExtLink></nav></div><span>{date}</span></article>)}</div></Section><Section id="skills" title={lang==="fr"?"Compétences":"Skills"} subtitle={t.skills.heading}><div className="list">{t.skills.groups.map(([group,items])=><article className="skill" key={group}><h3>{group}</h3><p>{items}</p></article>)}</div></Section><footer id="contact" className="footer"><h2 className="footerSectionTitle">Contact</h2><div className="footerContactGrid"><div><h3 className="footerHeadline">{t.contact.heading}</h3><span className="footerIntro">{t.contact.body}</span></div><div className="contactDetails"><div className="contactDetail"><span className="contactLabel">{lang==="fr"?"Localisation":"Location"}</span><div className="contactValue">{lang==="fr"?"Rabat, Maroc / Dakar, Sénégal":"Rabat, Morocco / Dakar, Senegal"}</div></div><div className="contactDetail"><span className="contactLabel">Email</span><div className="contactValue"><a href={mail}>diawbirane10@gmail.com</a></div></div></div></div><nav className="contactActions" aria-label="Contact links"><a className="contactAction email" href={mail} aria-label="Email" title="Email"><img src="data:image/png;base64," alt="" aria-hidden="true"/></a><a className="contactAction linkedin" href={linkedin} target="_blank" rel="noreferrer" aria-label="LinkedIn" title="LinkedIn"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="1" y="1" width="22" height="22" rx="4.5" fill="#0A66C2"/><path fill="#fff" d="M7.2 9.4H4.5V18h2.7V9.4zM5.85 5.2a1.56 1.56 0 1 0 0 3.12 1.56 1.56 0 0 0 0-3.12zM11.4 9.4H8.8V18h2.6v-4.25c0-1.12.21-2.2 1.6-2.2 1.37 0 1.39 1.28 1.39 2.27V18H17v-4.7c0-2.31-.5-4.08-3.2-4.08-1.3 0-2.17.71-2.53 1.39h-.04V9.4z"/></svg></a><a className="contactAction x" href={x} target="_blank" rel="noreferrer" aria-label="X" title="X"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817-5.966 6.817H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg></a><a className="contactAction github" href={github} target="_blank" rel="noreferrer" aria-label="GitHub" title="GitHub"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12 .297c-6.63 0-12 5.373-12 12 0 5.303 3.438 9.8 8.205 11.385.6.113.82-.258.82-.577 0-.285-.01-1.04-.015-2.04-3.338.724-4.042-1.61-4.042-1.61-.546-1.387-1.333-1.756-1.333-1.756-1.089-.745.083-.729.083-.729 1.205.084 1.839 1.237 1.839 1.237 1.07 1.835 2.809 1.305 3.495.998.108-.776.418-1.305.762-1.605-2.665-.3-5.466-1.332-5.466-5.93 0-1.31.465-2.38 1.235-3.22-.135-.303-.54-1.523.105-3.176 0 0 1.005-.322 3.3 1.23a11.5 11.5 0 0 1 3-.405c1.02.005 2.045.138 3 .405 2.28-1.552 3.285-1.23 3.285-1.23.645 1.653.24 2.873.12 3.176.765.84 1.23 1.91 1.23 3.22 0 4.61-2.805 5.625-5.475 5.92.42.36.81 1.096.81 2.22 0 1.606-.015 2.896-.015 3.286 0 .315.21.69.825.57C20.565 22.092 24 17.592 24 12.297c0-6.627-5.373-12-12-12"/></svg></a></nav></footer></>}
function ProjectDetail({project,t,lang}){return <><header className="projectHero"><ExtLink href="/">{t.detail[0]}</ExtLink><p>{project.no} · {project.field[lang]}</p><h1>{project.title}</h1><h2>{project.body[lang]}</h2></header><section className="detailGrid"><article><p>{t.detail[1]}</p><h2>{project.problem[lang]}</h2></article><article><p>{t.detail[2]}</p><h2>{project.solution[lang]}</h2></article><article><p>{t.detail[3]}</p><ol>{project.steps[lang].map(s=><li key={s}>{s}</li>)}</ol></article><article><p>{t.detail[4]}</p><h2>{project.discussion[lang]}</h2></article><article className="wide"><p>{t.detail[5]}</p><nav className="inline">{project.links.map(([label,href])=><ExtLink href={href} key={label}>{resourceLabel(label,lang)}</ExtLink>)}</nav></article></section></>}
export default function Portfolio(){const pathname=usePathname();const[lang,setLang]=useState("en");const[theme,setTheme]=useState("light");useEffect(()=>{const a=localStorage.getItem("ohmega-theme-v2"),b=localStorage.getItem("ohmega-lang");localStorage.removeItem("ohmega-theme");if(a)setTheme(a);if(b)setLang(b)},[]);useEffect(()=>{document.documentElement.dataset.theme=theme;document.documentElement.lang=lang;localStorage.setItem("ohmega-theme-v2",theme);localStorage.setItem("ohmega-lang",lang)},[theme,lang]);const t=useMemo(()=>copy[lang],[lang]);const slug=pathname?.startsWith("/projects/")?pathname.split("/projects/")[1]?.split("/")[0]:null;const project=projects.find(p=>p.slug===slug);return <main className="site"><Top t={t} lang={lang} setLang={setLang} theme={theme} setTheme={setTheme}/>{project?<ProjectDetail project={project} t={t} lang={lang}/>:<Home t={t} lang={lang}/>}</main>}
